public void suspend() {
    if(this.runningState != STATE_RUNNING) {
        throw new IllegalStateException("Stopwatch must be running to suspend. ");
    }
    stopTime = System.currentTimeMillis();
    this.runningState = STATE_SUSPENDED;
}
```

